fn spawn_it<F>(job: F) -> std::thread::JoinHandle<()>
where
    F: FnOnce() + Send + 'static,
{
    std::thread::spawn(job)
}

// Arc<i32> is Send + Sync, so this is accepted.
let value = std::sync::Arc::new(7);
spawn_it(move || println!("{value}")).join().unwrap();

